<?php
/**
 * 后台登录
 */
session_start();
define('IN_SITE', true);
require_once __DIR__ . '/../common/db.php';

$error = '';
$login_attempts = isset($_SESSION['login_attempts']) ? $_SESSION['login_attempts'] : 0;

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $username = isset($_POST['username']) ? trim($_POST['username']) : '';
    $password = isset($_POST['password']) ? trim($_POST['password']) : '';
    $captcha  = isset($_POST['captcha'])  ? trim($_POST['captcha'])  : '';

    // 验证码校验
    if (empty($captcha) || !isset($_SESSION['captcha']) || $captcha !== $_SESSION['captcha']) {
        $error = '验证码错误';
    } else {
        // 验证用户名密码
        $stmt = $conn->prepare("SELECT id, username, realname, role FROM admins WHERE username = ? AND password = MD5(?)");
        $stmt->bind_param("ss", $username, $password);
        $stmt->execute();
        $result = $stmt->get_result();

        if ($result->num_rows > 0) {
            $admin = $result->fetch_assoc();
            $_SESSION['admin_logged_in'] = true;
            $_SESSION['admin_id'] = $admin['id'];
            $_SESSION['admin_username'] = $admin['username'];
            $_SESSION['admin_realname'] = $admin['realname'];
            $_SESSION['admin_role'] = $admin['role'];
            $_SESSION['login_attempts'] = 0;

            // 更新最后登录时间
            $conn->query("UPDATE admins SET last_login = NOW() WHERE id = " . $admin['id']);

            header('Location: /admin/index.php');
            exit;
        } else {
            $login_attempts++;
            $_SESSION['login_attempts'] = $login_attempts;
            $error = '用户名或密码错误（第 ' . $login_attempts . ' 次尝试）';
        }
    }
}
