// 创建图片
$width = 120;
$height = 40;
$image = imagecreatetruecolor($width, $height);

// 背景色
$bg_color = imagecolorallocate($image, 240, 240, 240);
imagefill($image, 0, 0, $bg_color);

// 干扰点（少量，便于 OCR）
for ($i = 0; $i < 30; $i++) {
    $dot_color = imagecolorallocate($image, mt_rand(150, 220), mt_rand(150, 220), mt_rand(150, 220));
    imagesetpixel($image, mt_rand(0, $width), mt_rand(0, $height), $dot_color);
}

// 绘制验证码文字
$font_size = 5; // 内置字体大小
$colors = [
    imagecolorallocate($image, 40, 40, 40),
    imagecolorallocate($image, 20, 60, 120),
    imagecolorallocate($image, 120, 20, 20),
    imagecolorallocate($image, 20, 100, 20),
];

for ($i = 0; $i < 4; $i++) {
    $x = 15 + $i * 25;
    $y = 10 + mt_rand(-3, 3);
    $color = $colors[$i % count($colors)];
    imagestring($image, $font_size, $x, $y, $code[$i], $color);
}

// 输出
header('Content-Type: image/png');
header('Cache-Control: no-cache, no-store, must-revalidate');
header('Pragma: no-cache');
imagepng($image);
imagedestroy($image);
